__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"MOCK_DAPP_HTML",{enumerable:!0,get:function(){return n}});const n="<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>DApp Test Bridge - N.E.D Wallet</title>\n  <style>\n    body {\n      font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n      background-color: #FDF8F5;\n      padding: 16px;\n      margin: 0;\n      color: #111;\n    }\n    .header {\n      text-align: center;\n      margin-bottom: 20px;\n    }\n    .badge {\n      display: inline-block;\n      background: #00E5FF;\n      border: 2px solid #000;\n      border-radius: 6px;\n      padding: 4px 10px;\n      font-size: 11px;\n      font-weight: 900;\n      box-shadow: 2px 2px 0px #000;\n      margin-bottom: 8px;\n    }\n    h2 {\n      margin: 0;\n      font-size: 22px;\n      font-weight: 900;\n    }\n    p.subtitle {\n      margin: 4px 0 0;\n      font-size: 13px;\n      color: #666;\n    }\n    .card {\n      background: #FFFFFF;\n      border: 3px solid #000;\n      border-radius: 12px;\n      padding: 18px;\n      box-shadow: 4px 4px 0px #000;\n      margin-bottom: 20px;\n    }\n    button {\n      width: 100%;\n      padding: 14px;\n      font-size: 15px;\n      font-weight: 900;\n      border: 2px solid #000;\n      border-radius: 8px;\n      background-color: #E6F4FE;\n      cursor: pointer;\n      margin-bottom: 12px;\n      box-shadow: 2px 2px 0px #000;\n      transition: transform 0.1s;\n    }\n    button:active {\n      transform: translate(2px, 2px);\n      box-shadow: 0px 0px 0px #000;\n    }\n    button.sign-btn {\n      background-color: #35165E;\n      color: #FFF;\n    }\n    button:disabled {\n      opacity: 0.5;\n      cursor: not-allowed;\n      background-color: #E5E7EB;\n      color: #9CA3AF;\n    }\n    .console-title {\n      font-size: 13px;\n      font-weight: 800;\n      margin-bottom: 8px;\n      text-transform: uppercase;\n    }\n    .console {\n      background: #18181B;\n      color: #4ADE80;\n      padding: 14px;\n      border-radius: 10px;\n      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n      font-size: 12px;\n      height: 260px;\n      overflow-y: auto;\n      border: 3px solid #000;\n      box-shadow: 3px 3px 0px #000;\n    }\n    .log-line {\n      margin-bottom: 6px;\n      word-break: break-all;\n      line-height: 1.4;\n    }\n    .error { color: #F87171; }\n    .success { color: #38BDF8; font-weight: bold; }\n  </style>\n</head>\n<body>\n\n  <div class=\"header\">\n    <div class=\"badge\">TEST ENVIRONMENT</div>\n    <h2>DApp Test Bridge</h2>\n    <p class=\"subtitle\">Ki\u1ec3m th\u1eed k\u1ebft n\u1ed1i v\xed Web3 & k\xfd giao d\u1ecbch an to\xe0n</p>\n  </div>\n\n  <div class=\"card\">\n    <button id=\"connectBtn\">\ud83d\udd0c Connect Wallet</button>\n    <button id=\"signBtn\" class=\"sign-btn\" disabled>\u270d\ufe0f Sign Dummy Transaction</button>\n  </div>\n\n  <div class=\"console-title\">\ud83d\udda5\ufe0f Console Logs</div>\n  <div class=\"console\" id=\"consoleOutput\">\n    <div class=\"log-line\">Kh\u1edfi t\u1ea1o m\xf4i tr\u01b0\u1eddng DApp Test...</div>\n  </div>\n\n  <script src=\"https://unpkg.com/@solana/web3.js@1.87.0/lib/index.iife.js\"><\/script>\n\n  <script>\n    const connectBtn = document.getElementById('connectBtn');\n    const signBtn = document.getElementById('signBtn');\n    const consoleOutput = document.getElementById('consoleOutput');\n\n    function log(message, type = '') {\n      const div = document.createElement('div');\n      div.className = 'log-line ' + type;\n      div.textContent = '> ' + message;\n      consoleOutput.appendChild(div);\n      consoleOutput.scrollTop = consoleOutput.scrollHeight;\n      console.log(message);\n    }\n\n    // L\u1eafng nghe s\u1ef1 ki\u1ec7n Provider t\u1eeb useWeb3Bridge\n    window.addEventListener('solana#initialized', () => {\n      log('N.E.D Provider \u0111\xe3 s\u1eb5n s\xe0ng! (window.solana ready)', 'success');\n    });\n\n    if (window.solana) {\n      log('window.solana \u0111\xe3 \u0111\u01b0\u1ee3c t\xedch h\u1ee3p s\u1eb5n.', 'success');\n    }\n\n    connectBtn.addEventListener('click', async () => {\n      if (!window.solana) {\n        log('L\u1ed7i: Kh\xf4ng t\xecm th\u1ea5y window.solana bridge.', 'error');\n        return;\n      }\n      \n      try {\n        log('\u0110ang g\u1ecdi window.solana.connect()...');\n        const resp = await window.solana.connect();\n        const pk = resp && resp.publicKey ? resp.publicKey.toString() : (window.solana.publicKey ? window.solana.publicKey.toString() : 'Unknown');\n        log('K\u1ebft n\u1ed1i th\xe0nh c\xf4ng! Public Key: ' + pk, 'success');\n        signBtn.removeAttribute('disabled');\n        connectBtn.textContent = '\u2705 Connected: ' + pk.slice(0, 4) + '...' + pk.slice(-4);\n      } catch (err) {\n        log('K\u1ebft n\u1ed1i th\u1ea5t b\u1ea1i: ' + (err.message || err), 'error');\n      }\n    });\n\n    signBtn.addEventListener('click', async () => {\n      if (!window.solana || !window.solana.isConnected) {\n        log('L\u1ed7i: Vui l\xf2ng k\u1ebft n\u1ed1i v\xed tr\u01b0\u1edbc!', 'error');\n        return;\n      }\n\n      try {\n        log('\u0110ang t\u1ea1o v\xe0 g\u1eedi y\xeau c\u1ea7u signTransaction...');\n        \n        let userPk = window.solana.publicKey;\n        if (typeof userPk.toBase58 === 'function') {\n          userPk = userPk.toBase58();\n        } else {\n          userPk = userPk.toString();\n        }\n\n        const connection = new solanaWeb3.Connection('https://api.devnet.solana.com', 'confirmed');\n        const dummyKeypair = solanaWeb3.Keypair.generate();\n        \n        const { blockhash } = await connection.getLatestBlockhash('confirmed');\n        \n        const dummyTransaction = new solanaWeb3.Transaction({\n          recentBlockhash: blockhash,\n          feePayer: new solanaWeb3.PublicKey(userPk)\n        }).add(\n          solanaWeb3.SystemProgram.transfer({\n            fromPubkey: new solanaWeb3.PublicKey(userPk),\n            toPubkey: dummyKeypair.publicKey,\n            lamports: 100\n          })\n        );\n\n        const signedTx = await window.solana.signTransaction(dummyTransaction);\n        \n        log('K\xfd giao d\u1ecbch th\xe0nh c\xf4ng!', 'success');\n        const serialized = signedTx.serialize ? signedTx.serialize() : signedTx;\n        log('D\u1eef li\u1ec7u ch\u1eef k\xfd tr\u1ea3 v\u1ec1: ' + (serialized.length || 'OK') + ' bytes', 'success');\n      } catch (err) {\n        log('T\u1eeb ch\u1ed1i ho\u1eb7c l\u1ed7i k\xfd: ' + (err.message || err), 'error');\n      }\n    });\n  <\/script>\n</body>\n</html>"},4061,[]);
